"""Portable behavioral oracle; no fixed deployment paths in submitted tests."""
import os
from pathlib import Path

APP = Path(os.environ.get("BENCH_APP_ROOT", "/app"))
REPO = Path(os.environ.get("BENCH_REPO_ROOT", str(APP / "repo")))
SUITE = "import json\nimport os\nimport subprocess\nimport sys\nfrom pathlib import Path\nimport pytest\nfrom workflow import run\n\nPAYLOAD = json.loads(\"{\\\"batch_id\\\":\\\"contract\\\",\\\"records\\\":[{\\\"id\\\":\\\"r0\\\",\\\"year\\\":1900,\\\"month\\\":2,\\\"day\\\":29},{\\\"id\\\":\\\"r1\\\",\\\"year\\\":2000,\\\"month\\\":2,\\\"day\\\":29},{\\\"id\\\":\\\"r2\\\",\\\"year\\\":2023,\\\"month\\\":2,\\\"day\\\":29},{\\\"id\\\":\\\"r3\\\",\\\"year\\\":2024,\\\"month\\\":4,\\\"day\\\":31},{\\\"id\\\":\\\"r4\\\",\\\"year\\\":2024,\\\"month\\\":4,\\\"day\\\":30}]}\")\nEXPECTED = json.loads(\"{\\\"batch_id\\\":\\\"contract\\\",\\\"processed\\\":5,\\\"results\\\":[{\\\"id\\\":\\\"r0\\\",\\\"value\\\":false},{\\\"id\\\":\\\"r1\\\",\\\"value\\\":true},{\\\"id\\\":\\\"r2\\\",\\\"value\\\":false},{\\\"id\\\":\\\"r3\\\",\\\"value\\\":false},{\\\"id\\\":\\\"r4\\\",\\\"value\\\":true}],\\\"errors\\\":[]}\")\n\n\ndef test_batch_contract_and_published_file(tmp_path):\n    source, output = tmp_path / \"request.json\", tmp_path / \"nested\" / \"report.json\"\n    source.write_text(json.dumps(PAYLOAD), encoding=\"utf-8\")\n    original = source.read_text(encoding=\"utf-8\")\n    assert run(source, output) == EXPECTED\n    assert json.loads(output.read_text(encoding=\"utf-8\")) == EXPECTED\n    assert source.read_text(encoding=\"utf-8\") == original\n\n\ndef test_stop_policy_keeps_previous_output(tmp_path):\n    source, output, policy = tmp_path / \"bad.json\", tmp_path / \"report.json\", tmp_path / \"policy.json\"\n    source.write_text(json.dumps({\"batch_id\":\"bad\",\"records\":[{\"id\":\"bad\"}]}), encoding=\"utf-8\")\n    policy.write_text(json.dumps({\"on_error\":\"stop\"}), encoding=\"utf-8\")\n    output.write_text('{\"previous\": true}', encoding=\"utf-8\")\n    with pytest.raises(ValueError):\n        run(source, output, policy)\n    assert json.loads(output.read_text(encoding=\"utf-8\")) == {\"previous\":True}\n\n\ndef test_cli_from_other_working_directory(tmp_path):\n    source, output = tmp_path / \"request.json\", tmp_path / \"cli.json\"\n    source.write_text(json.dumps(PAYLOAD), encoding=\"utf-8\")\n    other = tmp_path / \"unrelated\"\n    other.mkdir()\n    result = subprocess.run([sys.executable,\"-B\",\"-m\",\"workflow\",str(source),str(output)], cwd=other,\n                            env=os.environ.copy(), capture_output=True, text=True, timeout=5)\n    assert result.returncode == 0, result.stderr\n    assert json.loads(output.read_text(encoding=\"utf-8\")) == EXPECTED\n    assert json.loads(result.stdout) == {\"batch_id\":\"contract\",\"processed\":len(PAYLOAD[\"records\"]),\"errors\":len(EXPECTED[\"errors\"])}\n\ndef test_integer_date_schema(tmp_path):\n    source, output = tmp_path / \"schema.json\", tmp_path / \"schema-out.json\"\n    records = [{\"id\":\"fraction\",\"year\":2024,\"month\":2,\"day\":29.0},\n               {\"id\":\"bool\",\"year\":True,\"month\":2,\"day\":28},\n               {\"id\":\"outside\",\"year\":10000,\"month\":1,\"day\":1}]\n    source.write_text(json.dumps({\"batch_id\":\"schema\",\"records\":records}), encoding=\"utf-8\")\n    assert run(source, output) == {\"batch_id\":\"schema\",\"processed\":3,\n                                  \"results\":[{\"id\":\"outside\",\"value\":False}],\n                                  \"errors\":[{\"id\":\"fraction\",\"code\":\"invalid_record\"},{\"id\":\"bool\",\"code\":\"invalid_record\"}]}\n"

def main():
    target = REPO / "tests" / "test_workflow.py"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(SUITE, encoding="utf-8")

if __name__ == "__main__":
    main()
